class Solution {
public:
    int minCost(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<bitset<1024>> dp(n);
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                bitset<1024> ways;
                if (i == 0 && j == 0) ways.set(grid[i][j]);
                else {
                    bitset<1024> prev;
                    if (i > 0) prev |= dp[j];
                    if (j > 0) prev |= dp[j-1];
                    for (int x = 0; x < 1024; ++x)
                        if (prev.test(x)) ways.set(x ^ grid[i][j]);
                }
                dp[j] = ways;
            }
        }
        for (int x = 0; x < 1024; ++x)
            if (dp[n-1].test(x)) return x;
        return -1;
    }
};
